import { createLogger } from '../utils/structuredLogger.js';

const logger = createLogger('env-validation');

/**
 * Required environment variables for all environments
 */
const REQUIRED_VARS = [
  'NODE_ENV',
  'PORT',
  'FRONTEND_URL',
  'SUPABASE_URL',
  'SUPABASE_ANON_KEY',
  'SUPABASE_SERVICE_ROLE_KEY',
  'JWT_SECRET',
];

/**
 * Required environment variables for production only
 */
const PRODUCTION_REQUIRED_VARS = [
  'JWT_REFRESH_SECRET',
  'PRODUCTION_FRONTEND_URL',
];

/**
 * Optional but recommended environment variables
 */
const RECOMMENDED_VARS = [
  'GROQ_API_KEY',
  'SMTP_USER',
  'SMTP_PASS',
  'UPSTASH_REDIS_REST_URL',
  'UPSTASH_REDIS_REST_TOKEN',
];

/**
 * Validate environment variable format
 */
const validators = {
  PORT: (value) => {
    const port = Number(value);
    if (isNaN(port) || port < 1 || port > 65535) {
      throw new Error('PORT must be a valid port number (1-65535)');
    }
  },

  NODE_ENV: (value) => {
    const trimmedValue = value.trim().toLowerCase();
    if (!['development', 'production', 'test', 'staging'].includes(trimmedValue)) {
      throw new Error(`NODE_ENV must be one of: development, production, test, staging (got: "${value}")`);
    }
  },

  SUPABASE_URL: (value) => {
    if (!value.startsWith('https://')) {
      throw new Error('SUPABASE_URL must start with https://');
    }
  },

  FRONTEND_URL: (value) => {
    if (!value.startsWith('http://') && !value.startsWith('https://')) {
      throw new Error('FRONTEND_URL must be a valid URL');
    }
  },

  JWT_SECRET: (value) => {
    if (value.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters long');
    }
  },

  JWT_REFRESH_SECRET: (value) => {
    if (value.length < 32) {
      throw new Error('JWT_REFRESH_SECRET must be at least 32 characters long');
    }
  },
};

/**
 * Validate all required environment variables
 */
export function validateEnvironment() {
  const errors = [];
  const warnings = [];
  const isProduction = process.env.NODE_ENV === 'production';

  // Check required variables
  const requiredVars = isProduction 
    ? [...REQUIRED_VARS, ...PRODUCTION_REQUIRED_VARS]
    : REQUIRED_VARS;

  for (const varName of requiredVars) {
    const value = process.env[varName];

    if (!value || value.trim() === '') {
      errors.push(`Missing required environment variable: ${varName}`);
      continue;
    }

    // Run specific validator if exists
    if (validators[varName]) {
      try {
        validators[varName](value);
      } catch (error) {
        errors.push(`Invalid ${varName}: ${error.message}`);
      }
    }
  }

  // Check recommended variables
  for (const varName of RECOMMENDED_VARS) {
    if (!process.env[varName]) {
      warnings.push(`Recommended environment variable not set: ${varName}`);
    }
  }

  // Log results
  if (errors.length > 0) {
    logger.error('Environment validation failed', { errors });
    console.error('\n❌ Environment Validation Errors:');
    errors.forEach(error => console.error(`  - ${error}`));
    console.error('\nPlease check your .env file and ensure all required variables are set.\n');
    process.exit(1);
  }

  if (warnings.length > 0) {
    logger.warn('Environment validation warnings', { warnings });
    console.warn('\n⚠️  Environment Validation Warnings:');
    warnings.forEach(warning => console.warn(`  - ${warning}`));
    console.warn('');
  }

  logger.info('Environment validation passed', {
    environment: process.env.NODE_ENV,
    requiredVarsCount: requiredVars.length,
    warningsCount: warnings.length,
  });

  console.log('✅ Environment validation passed');
}

/**
 * Get environment variable with fallback
 */
export function getEnv(key, defaultValue = undefined) {
  const value = process.env[key];
  if (value === undefined || value === '') {
    if (defaultValue === undefined) {
      throw new Error(`Environment variable ${key} is required but not set`);
    }
    return defaultValue;
  }
  return value;
}

/**
 * Get boolean environment variable
 */
export function getEnvBoolean(key, defaultValue = false) {
  const value = process.env[key];
  if (value === undefined || value === '') return defaultValue;
  return value.toLowerCase() === 'true' || value === '1';
}

/**
 * Get number environment variable
 */
export function getEnvNumber(key, defaultValue = undefined) {
  const value = process.env[key];
  if (value === undefined || value === '') {
    if (defaultValue === undefined) {
      throw new Error(`Environment variable ${key} is required but not set`);
    }
    return defaultValue;
  }
  const num = Number(value);
  if (isNaN(num)) {
    throw new Error(`Environment variable ${key} must be a number`);
  }
  return num;
}

/**
 * Startup Environment Validation
 * 
 * Implements fail-fast pattern for production configuration validation.
 * Inspired by concurrently v9's strict initialization checks.
 * 
 * Validates:
 * - Database connectivity environment variables
 * - Security-critical JWT configuration
 * - Production vs development configuration appropriateness
 * 
 * Pattern: Validate early, fail immediately, never start with insecure config
 */

const INSECURE_JWT_DEFAULT = 'preploop-jwt-secret-key';
const PRODUCTION_ENV = process.env.NODE_ENV === 'production';

/**
 * Get list of validation errors for current environment
 * @returns {string[]} Array of validation error messages (empty if valid)
 */
export function getProductionEnvValidationErrors() {
  const errors = [];

  // Check Supabase configuration
  if (!process.env.SUPABASE_URL) {
    errors.push('❌ SUPABASE_URL is not configured. Database connectivity will fail.');
  }

  if (!process.env.SUPABASE_ANON_KEY) {
    errors.push('❌ SUPABASE_ANON_KEY is not configured. Client-side API calls will fail.');
  }

  if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
    errors.push('❌ SUPABASE_SERVICE_ROLE_KEY is not configured. Server-side operations will fail.');
  }

  // Security check: reject insecure JWT defaults in production
  if (PRODUCTION_ENV) {
    const jwtSecret = process.env.JWT_SECRET || INSECURE_JWT_DEFAULT;

    if (jwtSecret === INSECURE_JWT_DEFAULT) {
      errors.push(
        '🔒 SECURITY FAILURE: JWT_SECRET must be explicitly configured in production. ' +
        'Using default secrets exposes authentication to compromise. ' +
        'Set JWT_SECRET environment variable to a strong, random secret.'
      );
    }

    if (!jwtSecret || jwtSecret.length < 32) {
      errors.push(
        '🔒 SECURITY WARNING: JWT_SECRET should be at least 32 characters in production ' +
        `(current: ${jwtSecret?.length || 0} chars).`
      );
    }
  }

  // Check for other critical configurations
  if (!process.env.FRONTEND_URL) {
    errors.push('⚠️  FRONTEND_URL is not configured. CORS validation may be overly permissive.');
  }

  return errors;
}

/**
 * Validate startup environment and throw if critical errors found
 * 
 * Uses fail-fast pattern: throws immediately with all validation errors
 * Does not allow partial failures in production
 * 
 * @throws {Error} If any validation errors are found
 */
export function validateStartupEnv() {
  const errors = getProductionEnvValidationErrors();

  if (errors.length > 0) {
    const fullMessage = [
      '🚨 STARTUP VALIDATION FAILED 🚨',
      'The application cannot start with these configuration issues:',
      '',
      ...errors,
      '',
      'Fix these issues before starting the application.',
    ].join('\n');

    console.error(fullMessage);
    throw new Error(`Startup validation failed: ${errors.length} error(s) found`);
  }

  console.log('✅ Startup environment validation passed');
}

/**
 * Generate debug information about current configuration
 * (Useful for troubleshooting, output safe for logs)
 */
export function getConfigDebugInfo() {
  return {
    nodeEnv: process.env.NODE_ENV || 'development',
    hasSupabaseUrl: !!process.env.SUPABASE_URL,
    hasSupabaseAnonKey: !!process.env.SUPABASE_ANON_KEY,
    hasSupabaseServiceRoleKey: !!process.env.SUPABASE_SERVICE_ROLE_KEY,
    hasJwtSecret: !!process.env.JWT_SECRET,
    jwtSecretLength: process.env.JWT_SECRET?.length || 0,
    hasFrontendUrl: !!process.env.FRONTEND_URL,
    timestamp: new Date().toISOString(),
  };
}

import { supabaseAdmin } from './supabaseClient.js';
import Groq from 'groq-sdk';

const EXTERNAL_AI_SYNC_ENABLED = process.env.ALLOW_EXTERNAL_AI_PROBLEM_SYNC === 'true';

const groq = new Groq({
    apiKey: process.env.GROQ_API_KEY, // Ensure this is available in your shell or .env
});

const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

async function main() {
    if (!EXTERNAL_AI_SYNC_ENABLED) {
        console.log('External AI sync is disabled. Set ALLOW_EXTERNAL_AI_PROBLEM_SYNC=true to run this script.');
        return;
    }

    console.log('Fetching problems without complete solutions...');

    // Fetch all problems
    const { data: problems, error } = await supabaseAdmin
        .from('problems')
        .select('id, title, description, solution_code')
        .order('id');

    if (error) {
        console.error('Error fetching problems:', error);
        return;
    }

    const missingSolutions = problems.filter(p => {
        const sol = p.solution_code || {};
        if (sol.python && sol.javascript && sol.cpp && sol.java) {
            return false;
        }
        return true;
    });

    console.log(`Found ${missingSolutions.length} problems needing solutions. Starting processing...`);

    let count = 0;

    for (const problem of missingSolutions) {
        try {
            console.log(`Processing [${problem.id}] ${problem.title}...`);

            const prompt = `
You are an expert algorithm software engineer. 
Write the optimal solution to the following LeetCode/DSA problem in 4 languages: Python, JavaScript, C++, and Java.
Do NOT include any test runner code, just the function or class definition. 
For Python, write classical \`class Solution:\` with \`def functionName(self, ...):\`.
Return the output ONLY as a minified valid JSON object containing exactly 4 keys: "python", "javascript", "cpp", "java", where each value is a raw string of the raw code. Do NOT attach markdown codeblocks (\`\`\`) outside the JSON.
Do NOT include any extra text. Make sure the JSON is totally valid.

Problem Title: ${problem.title}
`;
            const completion = await groq.chat.completions.create({
                model: 'llama-3.3-70b-versatile',
                messages: [{ role: 'user', content: prompt }],
                response_format: { type: 'json_object' }
            });

            const responseText = completion.choices[0].message.content;
            const parsedSol = JSON.parse(responseText);

            const existingSol = problem.solution_code || {};
            const newSol = {
                ...existingSol,
                python: parsedSol.python || existingSol.python,
                javascript: parsedSol.javascript || existingSol.javascript,
                cpp: parsedSol.cpp || existingSol.cpp,
                java: parsedSol.java || existingSol.java,
            };

            const { error: updateError } = await supabaseAdmin
                .from('problems')
                .update({ solution_code: newSol })
                .eq('id', problem.id);

            if (updateError) {
                console.error(`  -> Failed to update DB for [${problem.id}]`);
                if (process.env.NODE_ENV !== 'production') console.error('  -> Detail:', updateError.message);
            } else {
                console.log(`  -> Successfully updated ${problem.title}`);
                count++;
            }
        } catch (e) {
            console.error(`  -> Error processing problem [${problem.id}]`);
            if (process.env.NODE_ENV !== 'production') console.error('  -> Detail:', e.message);
        }

        // Wait 2s to not exceed rate limits (~ 30 RPM limit on free tier)
        await delay(2000);
    }

    console.log(`Finished! Successfully updated ${count} problems.`);
}

main();

