    const { data, error } = await supabaseAdmin
      .from('normalized_profiles')
      .update(updates)
      .eq('id', req.params.id)
      .eq('user_id', req.user.id)
      .select('*')
      .single();

    if (error || !data) {
      return res.status(404).json({ error: 'Portfolio profile not found or update failed' });
