router.post('/lint', optionalAuth, async (req, res) => {
  const { code, language } = req.body;

  if (!language || typeof language !== 'string') {
    return res.status(400).json({
      success: false,
      errors: [{ line: 1, col: 1, severity: 'error', message: 'Language is required' }],
    });
  }

  if (typeof code !== 'string') {
    return res.status(400).json({
      success: false,
      errors: [{ line: 1, col: 1, severity: 'error', message: 'Code must be a string' }],
    });
  }

  if (code.length > MAX_LINT_CODE_LENGTH) {
    return res.status(413).json({
      success: false,
      errors: [
        {
          line: 1,
          col: 1,
          severity: 'error',
          message: `Code is too large for live linting. Limit is ${MAX_LINT_CODE_LENGTH} characters.`,
        },
      ],
    });
  }

  const normalizedLanguage = normalizeLintLanguage(language);

  try {
    if (!code.trim()) {
      return res.json({ success: true, errors: [], checkedWith: 'none' });
    }

    if (normalizedLanguage === 'javascript') {
      try {
        new vm.Script(code);
        return res.json({ success: true, errors: [], checkedWith: 'js-parser' });
      } catch (err) {
        const raw = String(err?.stack || err?.message || 'Syntax error');
        const lineMatch = raw.match(/<anonymous>:(\d+)(?::(\d+))?/);
        const line = lineMatch?.[1] ? Math.max(1, Number(lineMatch[1])) : 1;
        const col = lineMatch?.[2] ? Math.max(1, Number(lineMatch[2])) : 1;
        return res.json({
          success: true,
          checkedWith: 'js-parser',
          errors: [
            { line, col, severity: 'error', message: String(err?.message || 'Syntax error') },
          ],
        });
      }
    }

    if (normalizedLanguage === 'python') {
      const pythonCmd = resolvePythonCommand();
      if (!pythonCmd) {
        return res.json({
          success: true,
          checkedWith: 'python-unavailable',
          errors: [
            {
              line: 1,
              col: 1,
              severity: 'warning',
              message: 'Python runtime not found for server lint checks',
            },
          ],
        });
      }

      const lintDir = fs.mkdtempSync(path.join(os.tmpdir(), 'preploop-lint-'));
      const lintFile = path.join(lintDir, 'lint.py');
      try {
        fs.writeFileSync(lintFile, code, 'utf-8');
        execFileSync(pythonCmd, ['-m', 'py_compile', lintFile], {
          stdio: 'pipe',
          timeout: 8000,
          cwd: lintDir,
        });
        return res.json({ success: true, errors: [], checkedWith: 'python-py-compile' });
      } catch (lintErr) {
        const stderr = lintErr?.stderr
          ? lintErr.stderr.toString()
          : lintErr?.message || 'Syntax error';
        return res.json({
          success: true,
          checkedWith: 'python-py-compile',
          errors: [extractPythonSyntaxError(stderr)],
        });
      } finally {
        try {
          fs.rmSync(lintDir, { recursive: true, force: true });
        } catch {}
      }
    }

    if (normalizedLanguage === 'c') {
      const cCmd = resolveCommand(['gcc', 'clang', 'C:\\Program Files\\LLVM\\bin\\clang.exe']);
      if (!cCmd) {
        return res.json({
          success: true,
          checkedWith: 'c-unavailable',
          errors: [
            {
              line: 1,
              col: 1,
              severity: 'warning',
              message: 'C compiler not found for server lint checks',
            },
          ],
        });
      }

      const lintDir = fs.mkdtempSync(path.join(os.tmpdir(), 'preploop-lint-'));
      const lintFile = path.join(lintDir, 'lint.c');
      try {
        fs.writeFileSync(lintFile, code, 'utf-8');
        execFileSync(cCmd, ['-fsyntax-only', lintFile], {
          stdio: 'pipe',
          timeout: 8000,
          cwd: lintDir,
        });
        return res.json({ success: true, errors: [], checkedWith: 'c-compiler' });
      } catch (lintErr) {
        const stderr = lintErr?.stderr
          ? lintErr.stderr.toString()
          : lintErr?.message || 'C syntax error';
        return res.json({
          success: true,
          checkedWith: 'c-compiler',
          errors: extractCompilerSyntaxErrors(stderr, 'C syntax error'),
        });
      } finally {
        try {
          fs.rmSync(lintDir, { recursive: true, force: true });
        } catch {}
      }
    }

    if (normalizedLanguage === 'cpp') {
      const cppCmd = resolveCommand([
        'g++',
        'clang++',
        'C:\\Program Files\\LLVM\\bin\\clang++.exe',
      ]);
      if (!cppCmd) {
        return res.json({
          success: true,
          checkedWith: 'cpp-unavailable',
          errors: [
            {
              line: 1,
              col: 1,
              severity: 'warning',
              message: 'C++ compiler not found for server lint checks',
            },
          ],
        });
      }

      const lintDir = fs.mkdtempSync(path.join(os.tmpdir(), 'preploop-lint-'));
      const lintFile = path.join(lintDir, 'lint.cpp');
      try {
        fs.writeFileSync(lintFile, code, 'utf-8');
        execFileSync(cppCmd, ['-fsyntax-only', lintFile], {
          stdio: 'pipe',
          timeout: 8000,
          cwd: lintDir,
        });
        return res.json({ success: true, errors: [], checkedWith: 'cpp-compiler' });
      } catch (lintErr) {
        const stderr = lintErr?.stderr
          ? lintErr.stderr.toString()
          : lintErr?.message || 'C++ syntax error';
        return res.json({
          success: true,
          checkedWith: 'cpp-compiler',
          errors: extractCompilerSyntaxErrors(stderr, 'C++ syntax error'),
        });
      } finally {
        try {
          fs.rmSync(lintDir, { recursive: true, force: true });
        } catch {}
      }
    }

    if (normalizedLanguage === 'java') {
      const javacCmd = resolveCommand(['javac']);
      if (!javacCmd) {
        return res.json({
          success: true,
          checkedWith: 'java-unavailable',
          errors: [
            {
              line: 1,
              col: 1,
              severity: 'warning',
              message: 'Java compiler not found for server lint checks',
            },
          ],
        });
      }

      const classMatch = code.match(/public\s+class\s+(\w+)/);
      const className = classMatch?.[1] || 'Main';
      const lintDir = fs.mkdtempSync(path.join(os.tmpdir(), 'preploop-lint-'));
      const generatedClassName = `${className}_${Date.now()}`;
      const lintFile = path.join(lintDir, `${generatedClassName}.java`);

      // Keep public class name aligned with filename to avoid false mismatch errors.
      const adjustedCode = classMatch?.[1]
        ? code.replace(/public\s+class\s+\w+/, `public class ${generatedClassName}`)
        : code;

      try {
        fs.writeFileSync(lintFile, adjustedCode, 'utf-8');
        execFileSync(javacCmd, [lintFile], { stdio: 'pipe', timeout: 10000, cwd: lintDir });
        return res.json({ success: true, errors: [], checkedWith: 'javac' });
      } catch (lintErr) {
        const stderr = lintErr?.stderr
          ? lintErr.stderr.toString()
          : lintErr?.message || 'Java syntax error';
        return res.json({
          success: true,
          checkedWith: 'javac',
          errors: extractCompilerSyntaxErrors(stderr, 'Java syntax error'),
        });
      } finally {
        try {
          fs.rmSync(lintDir, { recursive: true, force: true });
        } catch {}
      }
    }

    return res.json({ success: true, checkedWith: 'unsupported', errors: [] });
  } catch (error) {
    console.error('Code lint error:', error);
    return res.status(500).json({
      success: false,
      errors: [
        { line: 1, col: 1, severity: 'error', message: error.message || 'Failed to lint code' },
      ],
    });
  }
});

