  // Calculate score: percentage of user skills matched, weighted by similarity
  const score = matches.length > 0 
    ? Math.round((totalSimilarity / userSkills.length) * 100)
    : 0;
  
  return {
    score: Math.min(100, score),
    matches,
    coverage: Math.round((matches.length / userSkills.length) * 100),
  };
}

/**
 * Get skill clusters and related skills for UI recommendations
 */
export function getSkillRecommendations(skills = []) {
  const recommendations = new Set();
  
  for (const skill of skills) {
    const cluster = SKILL_SEMANTIC_CLUSTERS[skill] || [];
    cluster.forEach(related => {
      if (!skills.includes(related) && related !== skill) {
        recommendations.add(related);
      }
    });
  }
  
  return Array.from(recommendations).slice(0, 10);
}

/**
 * Batch compute embeddings for multiple skills
 */
export async function batchComputeEmbeddings(skills = []) {
  const embeddings = {};
  for (const skill of skills) {
    embeddings[skill] = await getSkillEmbedding(skill);
  }
  return embeddings;
}

/**
 * Store computed skill trends in database for trend detection
 */
export async function storeSkillTrends(skillTrendData) {
  try {
    const { data, error } = await supabaseAdmin
      .from('career_skill_trends')
      .insert(skillTrendData);
    
    if (error) throw error;
    return { success: true, data };
  } catch (err) {
    console.error('Error storing skill trends:', err);
    return { success: false, error: err.message };
  }
}

/**
 * Close Redis connection
 */
export async function closeRedisConnection() {
  if (redisClient) {
    await redisClient.quit();
    redisClient = null;
  }
}

export default {
  getSkillEmbedding,
  findSimilarSkills,
  computeSemanticSkillMatch,
  getSkillRecommendations,
  batchComputeEmbeddings,
  storeSkillTrends,
  closeRedisConnection,
};

/**
 * NLP-based Skill Trend Detection Service
 * 
 * Scans job descriptions to extract skills and detect emerging/declining trends.
 * Uses frequency analysis to identify skills trending up or down QoQ.
 */

import { supabase, supabaseAdmin } from '../db/supabaseClient.js';

/**
 * Common skill keywords for extraction
 */
const SKILL_KEYWORDS = {
  'programming': ['python', 'javascript', 'java', 'c++', 'go', 'rust', 'typescript', 'scala', 'kotlin', 'php', 'c#', 'ruby', 'perl', 'swift', 'r', 'matlab', 'objective-c', 'groovy'],
  'web': ['react', 'vue', 'angular', 'svelte', 'next.js', 'nuxt', 'express', 'django', 'flask', 'fastapi', 'spring', 'asp.net', 'node.js', 'html', 'css', 'webpack', 'vite'],
  'database': ['sql', 'mysql', 'postgresql', 'mongodb', 'redis', 'elasticsearch', 'cassandra', 'dynamodb', 'firestore', 'oracle', 'sqlite', 'mariadb', 'couchdb', 'neo4j'],
  'devops': ['docker', 'kubernetes', 'jenkins', 'gitlab', 'github', 'circleci', 'travis', 'terraform', 'ansible', 'vagrant', 'aws', 'azure', 'gcp', 'heroku', 'digitalocean', 'linux'],
  'ml_ai': ['machine learning', 'deep learning', 'tensorflow', 'pytorch', 'scikit-learn', 'keras', 'llm', 'nlp', 'computer vision', 'cv', 'transformers', 'bert', 'gpt', 'langchain', 'huggingface', 'openai', 'anthropic'],
  'data': ['pandas', 'numpy', 'spark', 'hadoop', 'hive', 'pig', 'etl', 'data pipeline', 'data warehouse', 'analytics', 'tableau', 'powerbi', 'dbt', 'airflow'],
  'mobile': ['ios', 'android', 'react native', 'flutter', 'xamarin', 'swift', 'kotlin'],
  'other': ['git', 'agile', 'scrum', 'jira', 'slack', 'rest api', 'graphql', 'microservices', 'cloud native', 'serverless', 'lambda'],
};

/**
 * Extract skills from job description text
 */
export function extractSkillsFromText(text) {
  if (!text) return [];
  
  const lowerText = text.toLowerCase();
  const extractedSkills = new Set();
  
  // Search for each skill keyword
  for (const [category, skills] of Object.entries(SKILL_KEYWORDS)) {
    for (const skill of skills) {
      // Match whole words or hyphenated terms
      const patterns = [
        new RegExp(`\\b${skill}\\b`, 'gi'),
        new RegExp(`\\b${skill.replace(/\s+/g, '[-\\s]+')}\\b`, 'gi'),
      ];
      
      for (const pattern of patterns) {
        if (pattern.test(lowerText)) {
          // Normalize skill name
          const normalized = skill.charAt(0).toUpperCase() + skill.slice(1);
          extractedSkills.add(normalized);
        }
      }
    }
  }
  
  return Array.from(extractedSkills);
}

/**
 * Analyze job description for skill mentions
 */
export function analyzeJobDescription(jobDescription) {
  const skills = extractSkillsFromText(jobDescription);
  
  return {
    text: jobDescription,
    skillsFound: skills,
    skillCount: skills.length,
    categories: categorizeSkills(skills),
    keywords: extractKeywords(jobDescription, 20),
  };
}

/**
 * Categorize skills by type
 */
function categorizeSkills(skills) {
  const categorized = {
    programming: [],
    web: [],
    database: [],
    devops: [],
    ml_ai: [],
    data: [],
    mobile: [],
    other: [],
  };
  
  for (const skill of skills) {
    const lower = skill.toLowerCase();
    for (const [category, keywords] of Object.entries(SKILL_KEYWORDS)) {
      if (keywords.includes(lower)) {
        categorized[category].push(skill);
        break;
      }
    }
  }
  
  return categorized;
}

/**
 * Extract top keywords from text
 */
function extractKeywords(text, limit = 20) {
  if (!text) return [];
  
  const words = text.toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 3);
  
  const stopWords = new Set(['the', 'and', 'for', 'with', 'from', 'that', 'this', 'will', 'have', 'your', 'role', 'position', 'job', 'work', 'team', 'skills', 'experience', 'required', 'must', 'should', 'need', 'able', 'about', 'also', 'plus', 'nice', 'knowledge']);
  
  const wordFreq = {};
  for (const word of words) {
    if (!stopWords.has(word)) {
      wordFreq[word] = (wordFreq[word] || 0) + 1;
    }
  }
  
  return Object.entries(wordFreq)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([word, freq]) => ({ word, frequency: freq }));
}

/**
 * Track skill mention frequency
 */
export async function trackSkillFrequency(jobs = []) {
  const skillFrequency = {};
  const skillAppearances = {};
  
  for (const job of jobs) {
    const description = job.description || job.title || '';
    const skills = extractSkillsFromText(description);
    
    for (const skill of skills) {
      if (!skillFrequency[skill]) {
        skillFrequency[skill] = 0;
        skillAppearances[skill] = [];
      }
      skillFrequency[skill]++;
      skillAppearances[skill].push({
        jobId: job.id,
        jobTitle: job.title,
        company: job.company,
      });
    }
  }
  
  return {
    skillFrequency,
    skillAppearances,
    totalJobs: jobs.length,
    uniqueSkills: Object.keys(skillFrequency).length,
  };
}

/**
 * Calculate skill trend for a specific skill across time periods
 */
export function calculateSkillTrend(historicalData) {
  if (!historicalData || historicalData.length < 2) {
    return { trend: 'insufficient_data', growthRate: 0 };
  }
  
  // Assume historicalData is sorted by time
  const recentPeriods = historicalData.slice(-4);
  const olderPeriods = historicalData.slice(0, Math.max(1, historicalData.length - 4));
  
  const recentAvg = recentPeriods.reduce((a, b) => a + b, 0) / recentPeriods.length;
  const olderAvg = olderPeriods.reduce((a, b) => a + b, 0) / olderPeriods.length;
  
  const growthRate = olderAvg > 0 ? ((recentAvg - olderAvg) / olderAvg) * 100 : 0;
  
  let trend = 'stable';
  if (growthRate > 20) trend = 'emerging';
  else if (growthRate > 10) trend = 'growing';
  else if (growthRate < -20) trend = 'declining';
  else if (growthRate < -10) trend = 'falling';
  
  return {
    trend,
    growthRate: Math.round(growthRate * 10) / 10,
    recentAverage: Math.round(recentAvg),
    olderAverage: Math.round(olderAvg),
  };
}

/**
 * Detect emerging skills across all jobs
 */
export async function detectEmergingSkillsFromJobs(jobs = []) {
  try {
    if (jobs.length === 0) {
      // Fetch recent jobs if not provided
      const { data, error } = await supabase
        .from('jobs')
        .select('id, title, description, company')
        .order('created_at', { ascending: false })
        .limit(500);
      
      if (error) throw error;
      jobs = data || [];
    }
    
    const frequency = await trackSkillFrequency(jobs);
    
    // Calculate trend for each skill
    const skillTrends = [];
    
    for (const [skill, count] of Object.entries(frequency.skillFrequency)) {
      const trend = {
        skill,
        frequency: count,
        frequencyPercentage: Math.round((count / jobs.length) * 100 * 10) / 10,
        appearances: frequency.skillAppearances[skill],
      };
      skillTrends.push(trend);
    }
    
    // Sort by frequency
    skillTrends.sort((a, b) => b.frequency - a.frequency);
    
    // Categorize as emerging (new), popular (top 20%), or niche
    const topSkills = skillTrends.slice(0, Math.ceil(skillTrends.length * 0.2));
    const popular = topSkills.filter(s => s.frequencyPercentage > 5);
    const emerging = skillTrends.filter(s => s.frequencyPercentage < 3 && s.frequencyPercentage > 0.5);
    
    return {
      timestamp: new Date().toISOString(),
      totalJobsAnalyzed: jobs.length,
      allSkills: skillTrends,
      popularSkills: popular,
      emergingSkills: emerging.slice(0, 20),
      statistics: {
        uniqueSkills: frequency.uniqueSkills,
        averageSkillsPerJob: Math.round((Object.values(frequency.skillFrequency).reduce((a, b) => a + b, 0) / jobs.length) * 10) / 10,
      },
    };
  } catch (err) {
    console.error('Error detecting emerging skills:', err);
    return { error: err.message };
  }
}

/**
 * Store skill trend data in database
 */
export async function storeSkillTrendData(skillName, quarter, frequency, trend) {
  try {
    const { data, error } = await supabase
      .from('career_market_signals')
      .upsert({
        skill_name: skillName,
        quarter,
        skill_mentions: frequency,
        trend_direction: trend,
        updated_at: new Date().toISOString(),
      }, {
        onConflict: ['skill_name', 'quarter'],
      });
    
    if (error) throw error;
    return { success: true, data };
  } catch (err) {
    console.error('Error storing skill trend:', err);
    return { success: false, error: err.message };
  }
}

/**
 * Get trending skills for a specific quarter
 */
export async function getTrendingSkillsForQuarter(quarter) {
  try {
    const { data, error } = await supabase
      .from('career_market_signals')
      .select('skill_name, skill_mentions, trend_direction')
      .eq('quarter', quarter)
      .order('skill_mentions', { ascending: false })
      .limit(30);
    
    if (error) throw error;
    
    return {
      quarter,
      skills: data || [],
      emerging: (data || []).filter(s => s.trend_direction === 'emerging'),
      declining: (data || []).filter(s => s.trend_direction === 'declining'),
    };
  } catch (err) {
    console.error('Error fetching trending skills:', err);
    return { error: err.message };
  }
}

/**
 * Get skills trend comparison between quarters
 */
export async function compareSkillTrends(skill, quarters = []) {
  try {
    const { data, error } = await supabase
      .from('career_market_signals')
      .select('quarter, skill_mentions')
      .eq('skill_name', skill)
      .in('quarter', quarters)
      .order('quarter', { ascending: true });
    
    if (error) throw error;
    
    const trend = calculateSkillTrend((data || []).map(d => d.skill_mentions));
    
    return {
      skill,
      quarters: (data || []).map(d => ({
        quarter: d.quarter,
        mentions: d.skill_mentions,
      })),
      trend,
    };
  } catch (err) {
    console.error('Error comparing skill trends:', err);
    return { error: err.message };
  }
}

export default {
  extractSkillsFromText,
  analyzeJobDescription,
  trackSkillFrequency,
  calculateSkillTrend,
  detectEmergingSkillsFromJobs,
  storeSkillTrendData,
  getTrendingSkillsForQuarter,
  compareSkillTrends,
};

import NodeCache from 'node-cache';
import { InterviewSimulatorService } from './aiService.js';

// Initialize cache with 10 minute TTL for interview data
const interviewCache = new NodeCache({ stdTTL: 600, checkperiod: 630 });

/**
 * Cached Interview Service
 * Wraps the InterviewSimulatorService with caching functionality
 */
export class CachedInterviewService {
  /**
   * Get interview session with caching
   */
  static async getInterviewSession(sessionId, userId) {
    // Try to get from cache first
    const cacheKey = `interview_session_${sessionId}`;
    const cachedSession = interviewCache.get(cacheKey);

    if (cachedSession && cachedSession.user_id === userId) {
      return cachedSession;
    }

    // If not in cache, get from the original service
    const session = await InterviewSimulatorService.getInterviewSession(sessionId, userId);

    // Cache the result
    interviewCache.set(cacheKey, session);

    return session;
  }

  /**
   * Initialize interview with caching
   */
  static async initializeInterview(
    userId,
    interviewType = 'dsa',
    difficulty = 'medium',
    companyFocus = null,
    requestId = null,
    interviewMode = null,
    totalQuestions = null
  ) {
    const result = await InterviewSimulatorService.initializeInterview(
      userId,
      interviewType,
      difficulty,
      companyFocus,
      requestId,
      interviewMode,
      totalQuestions
    );

    // Cache the new session
    const cacheKey = `interview_session_${result.sessionId}`;
    // We'll cache the session metadata for quick lookup
    const sessionMetadata = {
      sessionId: result.sessionId,
      userId,
      interviewType,
      difficulty,
      companyFocus,
      stage: result.stage,
      stageLabel: result.stageLabel
    };

    interviewCache.set(cacheKey, sessionMetadata);

    return result;
  }

  /**
   * Process interview response with caching
   */
  static async processInterviewResponse(sessionId, userId, candidateResponse, requestId = null, interviewMode = null) {
    try {
      const result = await InterviewSimulatorService.processInterviewResponse(
        sessionId, 
        userId, 
        candidateResponse, 
        requestId, 
        interviewMode
      );

      // Update cache with latest session state
      const cacheKey = `interview_session_${sessionId}`;
      const sessionMetadata = {
        sessionId,
        userId,
        stage: result.stage,
        stageLabel: result.stageLabel,
        current_scores: result.current_scores,
        continueInterview: result.continueInterview
      };

      interviewCache.set(cacheKey, sessionMetadata);

      return result;
    } catch (error) {
      // Return graceful fallback response
      return {
        interviewerMessage: "I'm having trouble processing your response. Could you rephrase?",
        feedback: 'Response processing temporarily unavailable. Please try again.',
        clarifications: [],
        hints: [],
        encouragement: 'No worries, let\'s try again.',
        continueInterview: true,
        fallback: true,
        error: true
      };
    }
  }

  /**
   * Complete interview and remove from cache
   */
  static async completeInterview(sessionId, userId, requestId = null) {
    const result = await InterviewSimulatorService.completeInterview(sessionId, userId, requestId);

    // Remove from cache since interview is completed
    const cacheKey = `interview_session_${sessionId}`;
    interviewCache.del(cacheKey);

    return result;
  }

  /**
   * Get cached session if available
   */
  static getCachedSession(sessionId) {
    return interviewCache.get(`interview_session_${sessionId}`);
  }

  /**
   * Clear session from cache
   */
  static clearCachedSession(sessionId) {
    const cacheKey = `interview_session_${sessionId}`;
    return interviewCache.del(cacheKey);
  }
}

/**
 * Real-time Collaboration Service
 * Enables peer-to-peer coding sessions with live code sharing
 */

import { WebSocketServer } from 'ws';
import { createLogger } from '../utils/structuredLogger.js';
import crypto from 'crypto';

const logger = createLogger('collaboration');

class CollaborationService {
  constructor() {
    this.sessions = new Map();
    this.users = new Map();
    this.wss = null;
  }

  /**
   * Initialize WebSocket server
   */
  initialize(server) {
    this.wss = new WebSocketServer({ server, path: '/ws/collaborate' });

    this.wss.on('connection', (ws, req) => {
      this.handleConnection(ws, req);
    });

    logger.info('Collaboration service initialized');
  }

  /**
   * Handle new WebSocket connection
   */
  handleConnection(ws, req) {
    const userId = this.extractUserId(req);

    if (!userId) {
      ws.close(1008, 'Unauthorized');
      return;
    }

    this.users.set(userId, { ws, userId, sessionId: null });

    ws.on('message', (data) => {
      this.handleMessage(userId, data);
    });

    ws.on('close', () => {
      this.handleDisconnect(userId);
    });

    ws.on('error', (error) => {
      logger.error('WebSocket error', { userId, error: error.message });
    });

    this.sendToUser(userId, {
      type: 'connected',
      userId,
    });
  }

  /**
   * Handle incoming messages
   */
  handleMessage(userId, data) {
    try {
      const message = JSON.parse(data.toString());

      switch (message.type) {
        case 'create_session':
          this.createSession(userId, message.data);
          break;

        case 'join_session':
          this.joinSession(userId, message.data.sessionId);
          break;

        case 'leave_session':
          this.leaveSession(userId);
          break;

        case 'code_change':
          this.broadcastCodeChange(userId, message.data);
          break;

        case 'cursor_move':
          this.broadcastCursorMove(userId, message.data);
          break;

        case 'chat_message':
          this.broadcastChatMessage(userId, message.data);
          break;

        case 'request_control':
          this.handleControlRequest(userId, message.data);
          break;

        default:
          logger.warn('Unknown message type', { type: message.type });
      }
    } catch (error) {
      logger.error('Failed to handle message', { error: error.message });
    }
  }

  /**
   * Create new collaboration session
   */
  createSession(userId, data) {
    const sessionId = this.generateSessionId();
    const session = {
      id: sessionId,
      host: userId,
      participants: new Set([userId]),
      code: data.initialCode || '',
      language: data.language || 'javascript',
      problem: data.problem || null,
      createdAt: Date.now(),
      settings: {
        maxParticipants: data.maxParticipants || 4,
        allowEditing: data.allowEditing !== false,
        requireApproval: data.requireApproval || false,
      },
    };

    this.sessions.set(sessionId, session);

    const user = this.users.get(userId);
    if (user) {
      user.sessionId = sessionId;
    }

    this.sendToUser(userId, {
      type: 'session_created',
      session: this.getSessionInfo(session),
    });

    logger.info('Session created', { sessionId, userId });
  }

  /**
   * Join existing session
   */
  joinSession(userId, sessionId) {
    const session = this.sessions.get(sessionId);

    if (!session) {
      this.sendToUser(userId, {
        type: 'error',
        message: 'Session not found',
      });
      return;
    }

    if (session.participants.size >= session.settings.maxParticipants) {
      this.sendToUser(userId, {
        type: 'error',
        message: 'Session is full',
      });
      return;
    }

    session.participants.add(userId);

    const user = this.users.get(userId);
    if (user) {
      user.sessionId = sessionId;
    }

    // Send current state to new participant
    this.sendToUser(userId, {
      type: 'session_joined',
      session: this.getSessionInfo(session),
    });

    // Notify other participants
    this.broadcastToSession(sessionId, {
      type: 'participant_joined',
      userId,
    }, userId);

    logger.info('User joined session', { sessionId, userId });
  }

  /**
   * Leave session
   */
  leaveSession(userId) {
    const user = this.users.get(userId);
    if (!user || !user.sessionId) return;

    const session = this.sessions.get(user.sessionId);
    if (!session) return;

    session.participants.delete(userId);
    user.sessionId = null;

    // Notify other participants
    this.broadcastToSession(session.id, {
      type: 'participant_left',
      userId,
    });

    // Delete session if empty
    if (session.participants.size === 0) {
      this.sessions.delete(session.id);
      logger.info('Session deleted', { sessionId: session.id });
    }

    logger.info('User left session', { sessionId: session.id, userId });
  }

  /**
   * Broadcast code changes
   */
  broadcastCodeChange(userId, data) {
    const user = this.users.get(userId);
    if (!user || !user.sessionId) return;

    const session = this.sessions.get(user.sessionId);
    if (!session) return;

    // Update session code
    session.code = data.code;

    // Broadcast to other participants
    this.broadcastToSession(user.sessionId, {
      type: 'code_change',
      userId,
      data: {
        code: data.code,
        changes: data.changes,
        timestamp: Date.now(),
      },
    }, userId);
  }

  /**
   * Broadcast cursor movements
   */
  broadcastCursorMove(userId, data) {
    const user = this.users.get(userId);
    if (!user || !user.sessionId) return;

    this.broadcastToSession(user.sessionId, {
      type: 'cursor_move',
      userId,
      data: {
        line: data.line,
        column: data.column,
      },
    }, userId);
  }

  /**
   * Broadcast chat messages
   */
  broadcastChatMessage(userId, data) {
    const user = this.users.get(userId);
    if (!user || !user.sessionId) return;

    this.broadcastToSession(user.sessionId, {
      type: 'chat_message',
      userId,
      data: {
        message: data.message,
        timestamp: Date.now(),
      },
    });
  }

  /**
   * Handle control request (for turn-based editing)
   */
  handleControlRequest(userId, data) {
    const user = this.users.get(userId);
    if (!user || !user.sessionId) return;

    const session = this.sessions.get(user.sessionId);
    if (!session) return;

    // Notify host
    this.sendToUser(session.host, {
      type: 'control_request',
      userId,
    });
  }

  /**
   * Handle disconnect
   */
  handleDisconnect(userId) {
    this.leaveSession(userId);
    this.users.delete(userId);
    logger.info('User disconnected', { userId });
  }

  /**
   * Send message to specific user
   */
  sendToUser(userId, message) {
    const user = this.users.get(userId);
    if (user && user.ws.readyState === 1) {
      user.ws.send(JSON.stringify(message));
    }
  }

  /**
   * Broadcast to all session participants
   */
  broadcastToSession(sessionId, message, excludeUserId = null) {
    const session = this.sessions.get(sessionId);
    if (!session) return;

    session.participants.forEach((participantId) => {
      if (participantId !== excludeUserId) {
        this.sendToUser(participantId, message);
      }
    });
  }

  /**
   * Get session info (without sensitive data)
   */
  getSessionInfo(session) {
    return {
      id: session.id,
      host: session.host,
      participants: Array.from(session.participants),
      code: session.code,
      language: session.language,
      problem: session.problem,
      settings: session.settings,
    };
  }

  /**
   * Get active sessions
   */
  getActiveSessions() {
    return Array.from(this.sessions.values()).map((session) => ({
      id: session.id,
      participants: session.participants.size,
      maxParticipants: session.settings.maxParticipants,
      language: session.language,
      createdAt: session.createdAt,
    }));
  }

  /**
   * Get session statistics
   */
  getStatistics() {
    return {
      activeSessions: this.sessions.size,
      activeUsers: this.users.size,
      totalParticipants: Array.from(this.sessions.values())
        .reduce((sum, s) => sum + s.participants.size, 0),
    };
  }

  // Helper methods
  extractUserId(req) {
    // Extract from query params or headers
    const url = new URL(req.url, 'http://localhost');
    return url.searchParams.get('userId');
  }

  generateSessionId() {
    return `session_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`;
  }
}

