export async function generateFresherScriptedQuestion(questionNumber, company, resumeContext, userAnswer = '', groqInjection = null) {
    const topic = getFresherQuestionTopic(questionNumber);
    if (!topic) return getFresherScriptedQuestion(questionNumber, company, resumeContext, userAnswer);

    try {
        const groq = groqInjection;
        if (!groq) {
            return getFresherFallbackQuestion(questionNumber, company, resumeContext, userAnswer);
        }

        const resumePrompt = formatResumeContextSimple(resumeContext);
        const topicAngles = {
            2: ['Ask about the most impactful project and the candidate\'s exact role.', 'Focus on what problem the project solved and how it was built.', 'Ask for the architecture/implementation story behind one resume project.'],
            3: ['Ask how the skill was used in a real project or assignment.', 'Ask why they consider it their strongest skill and how they proved it.', 'Ask for one example where that skill helped them solve a problem.'],
            4: ['Ask for the four principles and one example from their own work.', 'Ask them to explain OOP using a simple project scenario.', 'Ask how OOP helps them organize code in practice.'],
            5: ['Ask for the core difference and one practical use case for each.', 'Ask when they would choose one over the other in a project.', 'Ask them to compare both using a coding example.'],
            6: ['Ask what each key does in a database table design.', 'Ask how primary and foreign keys help relate tables.', 'Ask for a practical example of using both keys together.'],
            7: ['Ask why normalization matters for data consistency.', 'Ask what issue normalization solves in a database schema.', 'Ask how they would explain normalization in simple terms.'],
            8: ['Ask which language they prefer and why it fits their problem-solving style.', 'Ask what makes their preferred language practical for coding tasks.', 'Ask how they would describe the strengths of their favorite language.'],
            9: ['Ask the difference between GET and POST with a real API example.', 'Ask when they would choose GET over POST and why.', 'Ask how request semantics differ between GET and POST.'],
            10: ['Ask for a practical example that shows process vs thread.', 'Ask how a process and a thread differ in execution and memory.', 'Ask why the distinction matters in real systems.'],
            11: ['Ask them to explain one data structure they know well and when to use it.', 'Ask how they would choose between different data structures for a problem.', 'Ask for a practical example where they used a specific data structure.'],
        };
        const chosenAngleList = topicAngles[questionNumber] || [];
        const chosenAngle = chosenAngleList.length > 0
            ? chosenAngleList[crypto.randomInt(chosenAngleList.length)]
            : 'Ask the topic naturally and keep it fresher-friendly.';

        const userPrompt = `
Generate the next fresher interview question for question ${questionNumber} of 12 at ${company}.
Topic: ${topic}
Angle to use this run: ${chosenAngle}
${resumePrompt}
Requirements:
- Keep the question to 1-2 sentences max.
- Use the angle above, but paraphrase it naturally.
- For resume-based topics, ask about the candidate's resume/project/skill.
- For fundamentals topics, ask a clear fresher-friendly question.
- Return ONLY JSON: {"question":"..."}`;

        const completion = await aiCallWithRetry({
            operation: () => groq.chat.completions.create({
                model: 'llama-3.3-70b-versatile',
                messages: [
                    { role: 'system', content: 'You generate concise, realistic fresher interview questions. Return only JSON.' },
                    { role: 'user', content: userPrompt },
                ],
                response_format: { type: 'json_object' },
                temperature: 0.9,
            }),
            timeoutMs: 10000,
            maxRetries: 1,
            baseDelayMs: 200,
        });

        const parsed = safeJsonParseLocal(completion.choices?.[0]?.message?.content || '{}');
        const question = String(parsed?.question || '').trim();
        if (question) return question;
    } catch { }

    return getFresherFallbackQuestion(questionNumber, company, resumeContext, userAnswer);
}

function safeJsonParseLocal(text) {
    try { return JSON.parse(text); } catch {
        const fenced = text?.match(/```(?:json)?\s*([\s\S]*?)```/);
        if (fenced?.[1]) { try { return JSON.parse(fenced[1].trim()); } catch { } }
        return null;
    }
}

function formatResumeContextSimple(resumeContext) {
    if (!resumeContext || typeof resumeContext !== 'object') return '';
    const headline = String(resumeContext.candidateHeadline || '').trim();
    const summary = String(resumeContext.summary || '').trim();
    const coreSkills = Array.isArray(resumeContext.coreSkills) ? resumeContext.coreSkills.slice(0, 8) : [];
    const projectHighlights = Array.isArray(resumeContext.projectHighlights) ? resumeContext.projectHighlights.slice(0, 4) : [];
    if (!headline && !summary && coreSkills.length === 0 && projectHighlights.length === 0) return '';
    return `
## Candidate Resume Context
- Headline: ${headline || 'Not provided'}
- Summary: ${summary || 'Not provided'}
- Core skills: ${coreSkills.length > 0 ? coreSkills.join(', ') : 'Not provided'}
- Project highlights: ${projectHighlights.length > 0 ? projectHighlights.join(' | ') : 'Not provided'}`;
}

import { CircuitBreaker, CircuitBreakerOpenError } from '../utils/circuitBreaker.js';

const GITHUB_API_BASE = 'https://api.github.com';

// Circuit breaker for GitHub API calls
const githubBreaker = new CircuitBreaker('github', {
  failureThreshold: 5,
  resetTimeout: 60000, // 60 seconds
  halfOpenMaxAttempts: 2,
});

const githubHeaders = () => {
  const headers = {
    Accept: 'application/vnd.github+json',
    'User-Agent': 'Preploop-Portfolio-Generator',
  };

  if (process.env.GITHUB_TOKEN) {
    headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  }

  return headers;
};

const fetchJson = async (url) => {
  return githubBreaker.execute(async () => {
    const response = await fetch(url, { headers: githubHeaders() });
    if (!response.ok) {
      const body = await response.text();
      throw new Error(`GitHub API request failed (${response.status}): ${body}`);
    }

    return response.json();
  });
};

const fetchReadme = async (owner, repo) => {
  try {
    return githubBreaker.execute(async () => {
      const response = await fetch(`${GITHUB_API_BASE}/repos/${owner}/${repo}/readme`, {
        headers: githubHeaders(),
      });

      if (!response.ok) return '';
      const data = await response.json();
      if (!data?.content) return '';

      const decoded = Buffer.from(data.content, 'base64').toString('utf8');
      return decoded;
    });
  } catch (error) {
    if (error.isCircuitBreakerError) {
      console.error('[GitHub Circuit Breaker] Circuit open for readme fetch:', error.message);
    }
    return '';
  }
};

export const fetchGithubPortfolioData = async (username) => {
  const safeUsername = String(username || '').trim();
  if (!safeUsername) {
    return {
      username: null,
      profile: {},
      repositories: [],
      organizations: [],
    };
  }

  const [profile, repos, organizations] = await Promise.all([
    fetchJson(`${GITHUB_API_BASE}/users/${encodeURIComponent(safeUsername)}`),
    fetchJson(`${GITHUB_API_BASE}/users/${encodeURIComponent(safeUsername)}/repos?per_page=100&sort=updated`),
    fetchJson(`${GITHUB_API_BASE}/users/${encodeURIComponent(safeUsername)}/orgs`),
  ]);

  const repositories = await Promise.all(
    repos.map(async (repo) => {
      const readme = await fetchReadme(safeUsername, repo.name);
      return {
        id: repo.id,
        name: repo.name,
        description: repo.description,
        html_url: repo.html_url,
        homepage: repo.homepage,
        language: repo.language,
        stargazers_count: repo.stargazers_count,
        forks_count: repo.forks_count,
        pushed_at: repo.pushed_at,
        topics: repo.topics || [],
        pinned: false,
        readme,
      };
    }),
  );

  return {
    username: safeUsername,
    profile,
    repositories,
    organizations: organizations.map((org) => org.login),
  };
};

export default {
  fetchGithubPortfolioData,
};

const SECTION_HEADERS = {
  experience: /(?:^|\n)\s*(experience|work experience|professional experience)\s*(?:\n|$)/i,
  education: /(?:^|\n)\s*(education|academic background)\s*(?:\n|$)/i,
  skills: /(?:^|\n)\s*(skills|technical skills|tech stack)\s*(?:\n|$)/i,
};

const EMAIL_REGEX = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
const PHONE_REGEX = /(?:\+?\d{1,3}[\s-]?)?(?:\(?\d{2,4}\)?[\s-]?)?\d{3,4}[\s-]?\d{3,4}/g;

const trimLine = (line) => String(line || '').trim();

const getSectionText = (sourceText, sectionKey) => {
  const keys = Object.keys(SECTION_HEADERS);
  const currentPattern = SECTION_HEADERS[sectionKey];
  const currentMatch = sourceText.match(currentPattern);
  if (!currentMatch || currentMatch.index == null) return '';

  const start = currentMatch.index + currentMatch[0].length;
  let end = sourceText.length;

  for (const key of keys) {
    if (key === sectionKey) continue;
    const pattern = SECTION_HEADERS[key];
    const maybeMatch = sourceText.slice(start).match(pattern);
    if (maybeMatch && maybeMatch.index != null) {
      end = Math.min(end, start + maybeMatch.index);
    }
  }

  return sourceText.slice(start, end).trim();
};

const parseSkills = (text) => {
  if (!text) return { languages: [], frameworks: [], tools: [], domains: [] };

  const tokens = text
    .split(/[\n,|/]+/)
    .map((entry) => entry.replace(/^[-*•]\s*/, '').trim())
    .filter(Boolean);

  return {
    languages: tokens.slice(0, 10),
    frameworks: [],
    tools: [],
    domains: [],
  };
};

const parseExperience = (text) => {
  if (!text) return [];

  const lines = text
    .split('\n')
    .map(trimLine)
    .filter(Boolean);

  const result = [];
  for (let i = 0; i < lines.length; i += 2) {
    const roleLine = lines[i];
    const detailsLine = lines[i + 1] || '';
    const [rolePart, companyPart] = roleLine.split(/\sat\s/i);

    if (!rolePart) continue;

    result.push({
      role: rolePart.trim(),
      company: companyPart ? companyPart.trim() : 'Unknown',
      startDate: null,
      endDate: null,
      achievements: detailsLine ? [detailsLine] : [],
      source: 'resume',
    });
  }

  return result;
};

const parseEducation = (text) => {
  if (!text) return [];

  return text
    .split('\n')
    .map(trimLine)
    .filter(Boolean)
    .slice(0, 4)
    .map((line) => ({
      institute: line,
      degree: null,
      year: null,
      source: 'resume',
    }));
};

const parseBasicInfo = (resumeText) => {
  const lines = String(resumeText || '')
    .split('\n')
    .map(trimLine)
    .filter(Boolean);

  const fullName = lines[0] || null;
  const emailMatch = String(resumeText || '').match(EMAIL_REGEX);
  const phoneMatch = String(resumeText || '').match(PHONE_REGEX);

  return {
    fullName,
    title: lines[1] || null,
    email: emailMatch ? emailMatch[0] : null,
    phone: phoneMatch ? phoneMatch[0] : null,
    location: null,
    summary: lines.slice(2, 5).join(' ').slice(0, 280) || null,
    website: null,
  };
};

export const parseResumeToProfile = ({ text = '', uploadedFile = null } = {}) => {
  const safeText = String(text || '').trim();

  if (!safeText) {
    return {
      basicInfo: {},
      skills: { languages: [], frameworks: [], tools: [], domains: [] },
      experience: [],
      education: [],
      achievements: [],
      uploadedFile,
      parsedAt: new Date().toISOString(),
      confidenceScore: 0,
    };
  }

  const experienceText = getSectionText(safeText, 'experience');
  const educationText = getSectionText(safeText, 'education');
  const skillsText = getSectionText(safeText, 'skills');

  const parsed = {
    basicInfo: parseBasicInfo(safeText),
    skills: parseSkills(skillsText),
    experience: parseExperience(experienceText),
    education: parseEducation(educationText),
    achievements: [],
    uploadedFile,
    parsedAt: new Date().toISOString(),
    confidenceScore: 0.6,
  };

  const confidenceSignals = [
    parsed.basicInfo.fullName,
    parsed.basicInfo.email,
    parsed.experience.length > 0,
    parsed.education.length > 0,
    parsed.skills.languages.length > 0,
  ].filter(Boolean).length;

  parsed.confidenceScore = Number((confidenceSignals / 5).toFixed(2));
  return parsed;
};

export default {
  parseResumeToProfile,
};

/**
 * Real-time Interview WebSocket Service
 * Handles instant answer processing, live feedback, and streaming responses
 */
import { WebSocketServer } from 'ws';
import crypto from 'crypto';

// Lazy-initialize Groq to avoid duplicate SDK instances across the process.
// Uses a promise-based singleton so the first call initializes, subsequent calls reuse.
let _groqPromise = null;
async function getGroqClient() {
  if (_groqPromise) return _groqPromise;
  _groqPromise = (async () => {
    try {
      const { default: Groq } = await import('groq-sdk');
      return process.env.GROQ_API_KEY ? new Groq({ apiKey: process.env.GROQ_API_KEY }) : null;
    } catch {
      return null;
    }
  })();
  return _groqPromise;
}

class RealtimeInterviewService {
  constructor() {
    this.wss = null;
    this.sessions = new Map(); // sessionId -> { ws, context, state }
  }

  initialize(server) {
    this.wss = new WebSocketServer({ server, path: '/ws/interview' });

    this.wss.on('connection', (ws, req) => {
      const sessionId = this.generateSessionId();
      console.log(`[RealtimeInterview] New connection: ${sessionId}`);

      // Initialize session
      this.sessions.set(sessionId, {
        ws,
        context: {
          conversation: [],
          questionIndex: 0,
          company: 'General',
          role: 'Software Engineer',
          stage: 'Technical',
        },
        state: 'idle',
      });

      // Send welcome message
      ws.send(JSON.stringify({
        type: 'connected',
        sessionId,
        timestamp: Date.now(),
      }));

      // Handle messages
      ws.on('message', async (data) => {
        try {
          const message = JSON.parse(data.toString());
          await this.handleMessage(sessionId, message);
        } catch (err) {
          console.error('[RealtimeInterview] Message error:', err);
          ws.send(JSON.stringify({
            type: 'error',
            error: err.message,
          }));
        }
      });

      // Handle disconnect
      ws.on('close', () => {
        console.log(`[RealtimeInterview] Disconnected: ${sessionId}`);
        this.sessions.delete(sessionId);
      });

      ws.on('error', (err) => {
        console.error(`[RealtimeInterview] WebSocket error:`, err);
      });
    });

    console.log('[RealtimeInterview] WebSocket server initialized');
  }

  async handleMessage(sessionId, message) {
    const session = this.sessions.get(sessionId);
    if (!session) return;

    const { ws, context } = session;

    switch (message.type) {
      case 'start':
        await this.handleStart(session, message);
        break;

      case 'answer':
        await this.handleAnswer(session, message);
        break;

      case 'transcript':
        await this.handleTranscript(session, message);
        break;

      case 'ping':
        ws.send(JSON.stringify({ type: 'pong', timestamp: Date.now() }));
        break;

      default:
        console.warn(`[RealtimeInterview] Unknown message type: ${message.type}`);
    }
  }

  async handleStart(session, message) {
    const { ws, context } = session;
    const { company, role, stage, experienceLevel } = message;

    // Update context
    Object.assign(context, { company, role, stage, experienceLevel });

    // Generate first question
    const question = await this.generateQuestion(context);

    // Send question
    ws.send(JSON.stringify({
      type: 'question',
      question,
      questionIndex: 1,
      timestamp: Date.now(),
    }));

    context.conversation.push({
      role: 'interviewer',
      content: question,
      timestamp: Date.now(),
    });
    context.questionIndex = 1;
  }

  async handleAnswer(session, message) {
    const { ws, context } = session;
    const { answer, code, language } = message;

    // Add answer to conversation
    context.conversation.push({
      role: 'candidate',
      content: answer,
      code,
      language,
      timestamp: Date.now(),
    });

    // Send processing indicator
    ws.send(JSON.stringify({
      type: 'processing',
      timestamp: Date.now(),
    }));

    // Generate feedback and next question in parallel
    const [feedback, nextQuestion] = await Promise.all([
      this.generateFeedback(context, answer),
      this.generateNextQuestion(context),
    ]);

    // Send feedback
    ws.send(JSON.stringify({
      type: 'feedback',
      feedback: feedback.comment,
      score: feedback.score,
      strengths: feedback.strengths,
      improvements: feedback.improvements,
      timestamp: Date.now(),
    }));

    // Send next question
    ws.send(JSON.stringify({
      type: 'question',
      question: nextQuestion,
      questionIndex: context.questionIndex + 1,
      timestamp: Date.now(),
    }));

    context.conversation.push({
      role: 'feedback',
      content: feedback.comment,
      score: feedback.score,
      timestamp: Date.now(),
    });

    context.conversation.push({
      role: 'interviewer',
      content: nextQuestion,
      timestamp: Date.now(),
    });

    context.questionIndex++;
  }

  async handleTranscript(session, message) {
    const { ws } = session;
    const { text, isFinal } = message;

    // Echo transcript for confirmation (optional)
    ws.send(JSON.stringify({
      type: 'transcript_ack',
      text,
      isFinal,
      timestamp: Date.now(),
    }));
  }

  async generateQuestion(context) {
    const groq = await getGroqClient();
    if (!groq) {
      return this.getFallbackQuestion(context);
    }

    try {
      const prompt = `You are a ${context.company} interviewer conducting a ${context.stage} interview for a ${context.role} position.

Generate ONE interview question appropriate for this stage.

Rules:
- Be concise and clear
- Match the difficulty to the stage
- No markdown, just the question text

Question:`;

      const completion = await groq.chat.completions.create({
        model: 'llama-3.1-8b-instant',
        messages: [{ role: 'user', content: prompt }],
        temperature: 0.7,
        max_tokens: 200,
      });

      return completion.choices[0]?.message?.content?.trim() || this.getFallbackQuestion(context);
    } catch (err) {
      console.error('[RealtimeInterview] Question generation error:', err);
      return this.getFallbackQuestion(context);
    }
  }

  async generateNextQuestion(context) {
    const groq = await getGroqClient();
    if (!groq) {
      return this.getFallbackQuestion(context);
    }

    try {
      const recentConversation = context.conversation.slice(-6).map(m => ({
        role: m.role === 'interviewer' ? 'assistant' : 'user',
        content: m.content,
      }));

      const prompt = `Based on the conversation, generate the next interview question.

Rules:
- Build on previous answers
- Increase depth gradually
- Be concise
- No markdown

Next question:`;

      const completion = await groq.chat.completions.create({
        model: 'llama-3.1-8b-instant',
        messages: [
          ...recentConversation,
          { role: 'user', content: prompt },
        ],
        temperature: 0.7,
        max_tokens: 200,
      });

      return completion.choices[0]?.message?.content?.trim() || this.getFallbackQuestion(context);
    } catch (err) {
      console.error('[RealtimeInterview] Next question error:', err);
      return this.getFallbackQuestion(context);
    }
  }

  async generateFeedback(context, answer) {
    const groq = await getGroqClient();
    if (!groq) {
      return {
        comment: 'Good answer. Let me ask you a follow-up.',
        score: 75,
        strengths: ['Clear communication'],
        improvements: ['Add more detail'],
      };
    }

    try {
      const prompt = `Evaluate this interview answer:

Question: ${context.conversation[context.conversation.length - 2]?.content || 'Previous question'}
Answer: ${answer}

Provide feedback in JSON format:
{
  "comment": "brief feedback (1-2 sentences)",
  "score": number 0-100,
  "strengths": ["strength1", "strength2"],
  "improvements": ["improvement1", "improvement2"]
}`;

      const completion = await groq.chat.completions.create({
        model: 'llama-3.1-8b-instant',
        messages: [{ role: 'user', content: prompt }],
        temperature: 0.3,
        max_tokens: 300,
      });

      const raw = completion.choices[0]?.message?.content?.trim() || '';
      const jsonMatch = raw.match(/\{[\s\S]+\}/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[0]);
      }

      throw new Error('No JSON in response');
    } catch (err) {
      console.error('[RealtimeInterview] Feedback error:', err);
      return {
        comment: 'Good answer. Let me ask you a follow-up.',
        score: 75,
        strengths: ['Clear communication'],
        improvements: ['Add more detail'],
      };
    }
  }

  getFallbackQuestion(context) {
    const fallbacks = {
      'Technical': [
        'Can you explain the difference between a stack and a queue?',
        'How would you optimize a slow database query?',
        'What is your approach to debugging production issues?',
      ],
      'DSA / Coding': [
        'How would you reverse a linked list?',
        'Explain your approach to finding duplicates in an array.',
        'What is the time complexity of binary search?',
      ],
      'System Design': [
        'How would you design a URL shortening service?',
        'Explain how you would scale a web application.',
        'What are the trade-offs between SQL and NoSQL databases?',
      ],
      'Behavioral': [
        'Tell me about a time you faced a difficult technical challenge.',
        'How do you handle disagreements with team members?',
        'Describe a project you are most proud of.',
      ],
      'HR': [
        'Why do you want to work at our company?',
        'What are your career goals for the next 5 years?',
        'How do you handle stress and tight deadlines?',
      ],
    };

    const questions = fallbacks[context.stage] || fallbacks['Technical'];
    return questions[context.questionIndex % questions.length];
  }

  generateSessionId() {
    return `session_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`;
  }

  getActiveSessionCount() {
    return this.sessions.size;
  }
}

