export async function fetchAllIndianJobs(query = 'software developer', location = 'India') {
  console.log(`Fetching Indian jobs for: ${query}`);

  // Try all Indian job portals in parallel
  const [indeedJobs, naukriJobs, founditJobs, linkedinJobs] = await Promise.allSettled([
    fetchIndeedIndiaJobs(query, location),
    fetchNaukriJobs(query),
    fetchFounditJobs(query),
    fetchLinkedInIndiaJobs(query),
  ]);

  const allJobs = [
    ...(indeedJobs.status === 'fulfilled' ? indeedJobs.value : []),
    ...(naukriJobs.status === 'fulfilled' ? naukriJobs.value : []),
    ...(founditJobs.status === 'fulfilled' ? founditJobs.value : []),
    ...(linkedinJobs.status === 'fulfilled' ? linkedinJobs.value : []),
  ];

  if (allJobs.length === 0) {
    console.log('No jobs from Indian portals');
    return [];
  }

  console.log(`Got ${allJobs.length} jobs from Indian portals (Indeed: ${indeedJobs.status === 'fulfilled' ? indeedJobs.value.length : 0}, Naukri: ${naukriJobs.status === 'fulfilled' ? naukriJobs.value.length : 0}, Foundit: ${founditJobs.status === 'fulfilled' ? founditJobs.value.length : 0}, LinkedIn: ${linkedinJobs.status === 'fulfilled' ? linkedinJobs.value.length : 0})`);

  return allJobs.map(job => ({
    ...job,
    category: detectCategory(job.title, job.description),
    type: detectJobType(job.title, job.description),
    requirements: [],
    deadline: null,
    is_active: true,
    tags: [job.company, job.source, 'India'].filter(Boolean),
    logo_url: null,
  }));
}

function detectCategory(title, description = '') {
  const text = `${title} ${description}`.toLowerCase();
  if (text.includes('intern')) return 'internship';
  if (text.includes('fresher') || text.includes('entry') || text.includes('graduate') || text.includes('0-1 year') || text.includes('0 year')) return 'fresher';
  if (text.includes('campus')) return 'campus';
  return 'off-campus';
}

function detectJobType(title, description = '') {
  const text = `${title} ${description}`.toLowerCase();
  if (text.includes('intern')) return 'internship';
  if (text.includes('part-time') || text.includes('part time')) return 'part-time';
  if (text.includes('contract') || text.includes('freelance')) return 'contract';
  return 'full-time';
}

// WebSocket handler for real-time job updates
import { fetchAllIndianJobs } from './indianJobApis.js';
import { getCachedJobs, setCachedJobs } from './jobCache.js';

const connectedClients = new Set();
const UPDATE_INTERVAL = 5 * 60 * 1000; // 5 minutes
let updateTimer = null;

export function setupJobWebSocket(wss) {
  wss.on('connection', (ws, req) => {
    console.log('New WebSocket client connected for job updates');
    connectedClients.add(ws);

    // Send initial jobs
    sendJobUpdate(ws, 'software developer');

    ws.on('message', async (message) => {
      try {
        const data = JSON.parse(message);

        if (data.type === 'subscribe') {
          const query = data.query || 'software developer';
          await sendJobUpdate(ws, query);
        }
      } catch (error) {
        console.error('WebSocket message error:', error);
        ws.send(JSON.stringify({ error: 'Invalid message format' }));
      }
    });

    ws.on('close', () => {
      console.log('WebSocket client disconnected');
      connectedClients.delete(ws);

      if (connectedClients.size === 0 && updateTimer) {
        clearInterval(updateTimer);
        updateTimer = null;
      }
    });

    ws.on('error', (error) => {
      console.error('WebSocket error:', error);
      connectedClients.delete(ws);
    });

    // Start periodic updates if not already running
    if (!updateTimer && connectedClients.size > 0) {
      startPeriodicUpdates();
    }
  });
}

async function sendJobUpdate(ws, query) {
  try {
    const cacheKey = `jobs_${query}_1`;
    let jobs = getCachedJobs(cacheKey);

    if (!jobs) {
      jobs = await fetchAllIndianJobs(query, 'India');
      setCachedJobs(cacheKey, jobs);
    }

    ws.send(JSON.stringify({
      type: 'job_update',
      query,
      jobs: jobs.slice(0, 20),
      timestamp: new Date().toISOString(),
      cached: !!getCachedJobs(cacheKey)
    }));
  } catch (error) {
    console.error('Error sending job update:', error);
    ws.send(JSON.stringify({ 
      type: 'error', 
      message: 'Failed to fetch jobs' 
    }));
  }
}

function startPeriodicUpdates() {
  updateTimer = setInterval(async () => {
    if (connectedClients.size === 0) {
      clearInterval(updateTimer);
      updateTimer = null;
      return;
    }

    console.log(`Broadcasting job updates to ${connectedClients.size} clients`);

    const queries = ['software developer', 'data analyst', 'frontend developer'];

    for (const query of queries) {
      try {
        const jobs = await fetchAllIndianJobs(query, 'India');
        const cacheKey = `jobs_${query}_1`;
        setCachedJobs(cacheKey, jobs);

        const message = JSON.stringify({
          type: 'job_update',
          query,
          jobs: jobs.slice(0, 20),
          timestamp: new Date().toISOString(),
          cached: false
        });

        connectedClients.forEach(client => {
          if (client.readyState === 1) { // WebSocket.OPEN
            client.send(message);
          }
        });
      } catch (error) {
        console.error(`Error updating jobs for ${query}:`, error);
      }
    }
  }, UPDATE_INTERVAL);
}

export function broadcastJobUpdate(jobs, query) {
  const message = JSON.stringify({
    type: 'job_update',
    query,
    jobs,
    timestamp: new Date().toISOString()
  });

  connectedClients.forEach(client => {
    if (client.readyState === 1) {
      client.send(message);
    }
  });
}

import os from 'os';
import crypto from 'crypto';
import { createLogger } from './structuredLogger.js';

const logger = createLogger('performance-monitor');

class PerformanceMonitor {
  constructor(options = {}) {
    this.enabled = options.enabled ?? (process.env.NODE_ENV !== 'test');
    this.slowApiThreshold = options.slowApiThreshold || 500; // ms
    this.slowQueryThreshold = options.slowQueryThreshold || 1000; // ms
    this.metrics = {
      requests: new Map(),
      cache: { hits: 0, misses: 0, sets: 0 },
      errors: 0
    };
    this.startTime = Date.now();
  }

  recordRequest({ id, path, method, duration, status, error }) {
    if (!this.enabled) return;
    try {
      const entry = { id: id || this._genId(), path, method, duration, status, error: !!error, timestamp: Date.now(), slow: duration >= this.slowApiThreshold };
      this.metrics.requests.set(entry.id, entry);
      // keep size bounded
      if (this.metrics.requests.size > 1000) {
        const first = this.metrics.requests.keys().next().value;
        this.metrics.requests.delete(first);
      }
      if (error) this.metrics.errors++;
    } catch (e) {
      logger.debug('recordRequest failure', { err: e.message });
    }
  }

  recordCacheEvent(type, key) {
    if (!this.enabled) return;
    try {
      if (type === 'hit') this.metrics.cache.hits++;
      if (type === 'miss') this.metrics.cache.misses++;
      if (type === 'set') this.metrics.cache.sets++;
    } catch (e) {
      logger.debug('recordCacheEvent failure', { err: e.message });
    }
  }

  getMetrics() {
    const totalRequests = this.metrics.requests.size;
    const avgResponse = totalRequests > 0 ? Array.from(this.metrics.requests.values()).reduce((s, r) => s + (r.duration || 0), 0) / totalRequests : 0;
    return {
      uptimeMs: Date.now() - this.startTime,
      requests: { total: totalRequests, avgResponseMs: Math.round(avgResponse) },
      cache: this.metrics.cache,
      errors: this.metrics.errors,
      system: {
        cpus: os.cpus().length,
        freeMem: os.freemem(),
        totalMem: os.totalmem()
      }
    };
  }

  _genId() {
    return `pm_${Date.now()}_${crypto.randomBytes(5).toString('hex')}`;
  }
}

const performanceMonitor = new PerformanceMonitor({
  enabled: process.env.PERF_MONITOR_ENABLED !== 'false'
});

export default performanceMonitor;
export { PerformanceMonitor };

